  `Matcher` varchar(20) DEFAULT NULL,
  `CResin` varchar(50) DEFAULT NULL,
  `PRICE1` decimal(19,4) DEFAULT NULL,
  `EN71` varchar(1) DEFAULT NULL,
  `AP89` varchar(1) DEFAULT NULL,
  `EU94` varchar(1) DEFAULT NULL,
  `JHOSPA` varchar(1) DEFAULT NULL,
  `EU2002` varchar(1) DEFAULT NULL,
  `ROH52` varchar(1) DEFAULT NULL,
  `MAT10` varchar(1) DEFAULT NULL,
  `NA` varchar(1) DEFAULT NULL,
  `Othe` varchar(40) DEFAULT NULL,
